    -- Initialize boss and raid options
    function Features.initializeBossAndRaidOptions()
        Runtime.dataTable49.Default = Runtime.tweenSafeIfHaveItems
        Runtime.createToggle23(Runtime.dataTable49, function(argumentValue)
            if argumentValue then
                spawn(function()
                    while Settings["Tween Safe if have Items"] do
                        if wait(0.25) then
                            pcall(function()
                                if CheckNameBoss("Darkbeard") and Settings["Attack Darkbeard"] then
                                    return
                                end
                                if DetectItemPlr("Fist of Darkness") and Settings["Summon Darkbeard"] then
                                    return
                                end
                                if DetectItemPlr("Fist of Darkness") then
                                    if not Settings["Tween Safe if have Items"] then
                                        return
                                    end
                                    do
                                        if game.PlaceId ~= getgenv().CheckPlaceId2 then
                                            toTarget(CFrame.new(-12463.8740234375, 374.91445922851562, -7523.77392578125))
                                            return
                                        end
                                        toTarget(CFrame.new(-385.250916, 73.0458984, 297.388397))
                                        return
                                    end
                                else
                                    if not DetectItemPlr("God's Chalice") then
                                        return
                                    end
                                    if not Settings["Tween Safe if have Items"] then
                                        return
                                    end
                                    do
                                        if game.PlaceId ~= getgenv().CheckPlaceId2 then
                                            toTarget(CFrame.new(-12463.8740234375, 374.91445922851562, -7523.77392578125))
                                            return
                                        end
                                        toTarget(CFrame.new(-385.250916, 73.0458984, 297.388397))
                                        return
                                    end
                                end
                            end)
                            continue
                        end
                        break
                    end
                end)
            end
            SaveSettings("Tween Safe if have Items", argumentValue)
        end)
