        SelectSkillsSection = SettingSkillMain.CreateSection("Select Skills")

        local callback3 = function(y, options)
            local text, data = "Select Skills " .. y, {}
            for i, option in ipairs(options) do
                dataTable[option] = false
            end
            EnsureAllTrueDefaults(text, options)
            y = PrepareMultiSelectList(dataTable, Settings[text], true)
            dataTable, options = SelectSkillsSection.CreateDropdown, {Title = text, List = y, Search = true, Selected = true}
            options.Default = Settings[text] or nil
            dataTable(options, function(y, argumentValue)
                SaveSettings(text, y, argumentValue)
            end)
        end

        callback3("Melee", {"Z", "X", "C"})
        callback3("Sword", {"Z", "X"})
        callback3("Gun", {"Z", "X"})
        callback3("Blox Fruit", {
            "Z",
            "X",
            "C",
            "V",
            "F",
        })
        HoldSkillsSection = SettingSkillMain.CreateSection("Hold Skills")
        Runtime.guardKey38 = 3118851069

        function Runtime.callback18(y, argumentValue)
            local dataTable = {}
            for i, value in ipairs(argumentValue) do
                dataTable[value] = {
                    Title = value,
                    KeyName = value,
                    Min = 0,
                    Max = 5,
                    Default = Settings["Skill " .. value .. " " .. y] or 0.5,
                    Precise = true,
                }
            end
            HoldSkillsSection.CreateDropdown({Title = "Set Delay " .. y, List = dataTable, Slider = true}, function(selection, options)
                if not options then
                    return
                end
                if not options.KeyName then
                    return
                end
                SaveSettings("Skill " .. options.KeyName .. " " .. y, options.Default)
            end)
        end

        Runtime.createToggle21 = HoldSkillsSection.CreateToggle
