            pcall(Runtime.environment6.notify, "Chuoi Hub", "Script đã chạy trước đó, không chạy lại lần 2.", 5)
        end
    else
        pcall(Runtime.environment6.notifyLua, "Script đã chạy trước đó, không chạy lại lần 2.", "Chuoi Hub", 5)
    end
    print("[Chuoi Hub] Script loader is already active in this session.")
    return
end
